(* [comment removed for export] *)
Ltac brute_regZ0 n r lo cnt g :=
  let w := getreg n in
  lazymatch w with
  | Z_to_bv 64 ?e =>
      let F := eval pattern r in e in
      lazymatch F with
      | ?f r =>
          let H := fresh "BR" in
          assert (H : forall r0, lo <= r0 < lo + cnt -> (f r0 =? g r0) = true)
            by (apply (brute_range (fun r0 => f r0 =? g r0) lo cnt); vm_compute; reflexivity);
          replace e with (g r) by (symmetry; apply Z.eqb_eq; apply H; lia);
          clear H
      end
  | _ => fail "brute_regZ0: register" n "holds" w
  end.

Lemma ax2_le64pc : forall (RNG : footprint) (Q : machine_state -> Prop) (mm : amem) (SS r : Z) (src : list Z)
    (ra sp gp tp x6 x7 x8 x9 a0 a1 a2 a3 a4 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32),
  bytes_at asegs mm SS (map (Z_to_bv 8) src) -> 8 <= zlen src < 2^26 -> 16 <= SS -> SS + zlen src <= 2^47 ->
  rng RNG SS (zlen src) -> 1 <= r <= 255 ->
  (forall (cw x5' x6' x13' x15' x16' : word),
     evtF asegs RNG Q (MS (mkR ra sp gp tp x5' x6' cw x8 x9 a0 a1 a2 x13' a4 x15' x16' a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11
                              (Z_to_bv 64 (zlen src + -8)) (Z_to_bv 64 (8 - Z.log2 r)) t5 t6)
                         F (Z_to_bv 64 0x83edc) fc None mm (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR ra sp gp tp (Z_to_bv 64 r) x6 x7 x8 x9 a0 a1 a2 a3 a4 (Z_to_bv 64 (SS + zlen src + -8)) a6 a7
                           s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 (Z_to_bv 64 (zlen src + -8)) t4 t5 t6)
                       F (Z_to_bv 64 0x83c54) fc None mm (seg_rom asegs)).
